{
  "nombre": "Base de datos de practica",
  "descripcion": "Servicio de demostracion para la sustentacion",
  "configuracion": {
    "imagenDocker": "postgres:16-alpine",
    "cpuAsignado": 0.5,
    "memoriaAsignada": 256,
    "almacenamientoAsignado": 1024,
    "puertos": [
      { "host": 55432, "contenedor": 5432, "protocolo": "tcp" }
    ],
    "variablesEntorno": {
      "POSTGRES_PASSWORD": "clave_de_prueba"
    },
    "volumenes": []
  }
}

{
  "nombre": "Imagenes en Docker",
  "contenido": [
    {
      "tipo": "texto",
      "contenido": "Las imagenes son los objetos tipo 'clase' de programas, aplicaciones o servicios que luego se 'instancian' en forma de contenedores."
    },
    {
      "tipo": "imagen",
      "url": "{{urlImagenModulo}}",
      "textoAlternativo": "Diagrama de capas de una imagen Docker"
    },
    {
      "tipo": "enlace",
      "url": "https://docs.docker.com/get-started/docker-concepts/the-basics/what-is-an-image/",
      "titulo": "Documentacion oficial: que es una imagen Docker",
      "descripcion": "Referencia externa para ampliar el modulo"
    }
  ],
  "orden": 3
}

{
  "nombre": "Introduccion a contenedores",
  "contenido": [
    {
      "tipo": "texto",
      "contenido": "Los contenedores empaquetan una aplicacion y sus dependencias en una unidad ejecutable aislada."
    }
  ],
  "orden": 1
}

{
  "nombre": "Redes en Docker",
  "contenido": [
    {
      "tipo": "texto",
      "contenido": "Docker crea redes virtuales para que los contenedores se comuniquen entre si de forma aislada."
    }
  ],
  "orden": 2
}

{
  "descripcion": "Despliega un servicio con la imagen nginx y al menos un volumen",
  "criteriosValidacion": {
    "operacion": "desplegar",
    "condiciones": {
      "imagenDocker": "nginx",
      "volumenesMinimos": 1
    }
  },
  "orden": 1
}

{
  "titulo": "Evaluacion: Introduccion a contenedores",
  "preguntas": [
    {
      "pregunta": "Cual es la diferencia entre un volumen y un bind mount?",
      "opciones": [
        "No hay diferencia, son sinonimos",
        "El volumen lo administra Docker; el bind mount apunta a una ruta del host",
        "El bind mount solo funciona en Windows",
        "El volumen no persiste datos"
      ],
      "respuestaCorrecta": 1
    }
  ],
  "fechaDisponible": "2020-01-01T00:00:00.000Z"
}
